<?php require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require_permission('manage_suppliers');
$err='';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=$_POST['action']??'add';try{
 if($action==='add'){$st=db()->prepare('INSERT INTO suppliers(party_code,party_name,mobile,gstin,address) VALUES(?,?,?,?,?)');$st->execute([trim($_POST['party_code']??''),trim($_POST['party_name']??''),trim($_POST['mobile']??''),trim($_POST['gstin']??''),trim($_POST['address']??'')]);audit('SUPPLIER_CREATE','supplier',(int)db()->lastInsertId());$msg='Supplier added.';}
 elseif($action==='payment'){$sid=(int)($_POST['supplier_id']??0);$amt=(float)($_POST['amount']??0);$remarks=trim($_POST['remarks']??'');if($amt<=0)throw new Exception('Payment amount must be positive.');db()->prepare("INSERT INTO supplier_ledger(supplier_id,txn_type,debit,reference_type,remarks,created_by) VALUES(?,'PAYMENT',?,'PAYMENT',?,?)")->execute([$sid,$amt,$remarks,current_user()['id']]);audit('SUPPLIER_PAYMENT','supplier',$sid,['amount'=>$amt]);$msg='Supplier payment posted.';}
 }catch(Throwable $e){$err='Could not save: '.$e->getMessage();}}
$rows=db()->query("SELECT s.*,COALESCE(SUM(sl.credit-sl.debit),0) outstanding FROM suppliers s LEFT JOIN supplier_ledger sl ON sl.supplier_id=s.id GROUP BY s.id ORDER BY s.id DESC")->fetchAll();page_header('Supplier / Party Master');if($err)echo '<div class="notice error">'.e($err).'</div>';if($msg)echo '<div class="notice success">'.e($msg).'</div>'; ?>
<form method="post" class="panel"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><div class="row3"><div><label>Party ID / Code</label><input name="party_code" required placeholder="PTY-001"></div><div><label>Party Name</label><input name="party_name" required></div><div><label>Mobile</label><input name="mobile"></div></div><br><div class="row"><div><label>GSTIN</label><input name="gstin"></div><div><label>Address</label><input name="address"></div></div><br><button class="btn">Add Party</button></form><br>
<table><tr><th>Party ID</th><th>Name</th><th>Mobile</th><th>GSTIN</th><th>Outstanding Payable</th><th>Post Payment</th><th>Edit</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['party_code'])?></td><td><?=e($r['party_name'])?></td><td><?=e($r['mobile'])?></td><td><?=e($r['gstin'])?></td><td>₹<?=e(number_format($r['outstanding'],2))?></td><td><form method="post" class="actions"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="payment"><input type="hidden" name="supplier_id" value="<?=$r['id']?>"><input type="number" name="amount" min="0.01" step="0.01" placeholder="Amount" style="width:110px" required><input name="remarks" placeholder="Ref" style="width:100px"><button class="btn secondary">Post</button></form></td><td><a href="supplier_edit.php?id=<?=$r['id']?>">Edit</a></td></tr><?php endforeach;?></table><?php page_footer();
